UPDATE diag_questions SET choices_json = '[{"choice_id":"A","text":"''밤''은 화자가 피하고 싶은 부정적 시간이고, ''간''은 용왕에게 불필요한 물건이다.","vector":{"논리 사고력":-5},"error_path":"전제 누락"},{"choice_id":"B","text":"''밤''은 임의 부재를 상징하고, ''간''은 용왕의 권위를 상징한다.","vector":{"논리 사고력":-5},"error_path":"인과 관계 왜곡"},{"choice_id":"C","text":"''밤''은 임과 함께하고 싶은 긍정적 시간으로 변용 가능하며, ''간''은 토끼와 용왕 모두에게 생명과 직결된 중요한 대상이다.","vector":{"논리 사고력":10,"문장 독해력":5,"구조 독해력":3,"국어 관련 배경지식":2,"문제 분석 및 전략 수립 능력":1,"선택지 분석 및 전략 수립 능력":1},"error_path":"정답"},{"choice_id":"D","text":"''밤''과 ''간''은 모두 현실에서 존재하지 않는 환상적인 소재이다.","vector":{"논리 사고력":-5},"error_path":"조건 혼동"},{"choice_id":"E","text":"''밤''은 절대적인 길이를 가진 물리적 시간이고, ''간''은 토끼가 숨길 수 있는 물리적 신체 부위이다.","vector":{"논리 사고력":-5},"error_path":"범위 과확대"}]' WHERE id = 'R1_LIT_P5_Q02';
