UPDATE diag_questions SET choices_json = '[{"choice_id":"A","text":"간세포가 사이토카인을 과다 분비하여 스스로 사멸했기 때문이다.","vector":{"논리 사고력":-5},"error_path":"기제 오해"},{"choice_id":"B","text":"바이러스가 간세포 내에서 증식하여 세포를 직접 터뜨렸기 때문이다.","vector":{"논리 사고력":-5},"error_path":"인과 관계 단순화"},{"choice_id":"C","text":"활성화된 방관자 킬러 T세포가 감염되지 않은 정상 간세포까지 공격했기 때문이다.","vector":{"논리 사고력":10,"문장 독해력":5,"구조 독해력":3,"비문학 배경지식":3,"문제 분석 및 전략 수립 능력":1,"선택지 분석 및 전략 수립 능력":1},"error_path":"정답"},{"choice_id":"D","text":"항원 특이 T세포가 바이러스에 감염된 간세포만을 선택적으로 제거했기 때문이다.","vector":{"논리 사고력":-5},"error_path":"정상 면역 반응 설명"},{"choice_id":"E","text":"면역 체계가 작동을 멈추어 바이러스 방어에 실패했기 때문이다.","vector":{"논리 사고력":-5},"error_path":"상황 오해"}]' WHERE id = 'W1_NON_P5_Q07';
UPDATE diag_questions SET choices_json = '[{"choice_id":"A","text":"암세포는 잘 죽이지만 바이러스는 죽이지 못한다.","vector":{"문장 독해력":-5},"error_path":"능력 제한 오해"},{"choice_id":"B","text":"사이토카인에는 반응하지만 케모카인에는 반응하지 않는다.","vector":{"문장 독해력":-5},"error_path":"특성 오해"},{"choice_id":"C","text":"초기 바이러스 방어에는 유리하지만, 과도하면 정상 조직 손상을 유발할 수 있다.","vector":{"문장 독해력":10,"어휘력":3,"구조 독해력":2,"비문학 배경지식":3,"문제 분석 및 전략 수립 능력":1,"선택지 분석 및 전략 수립 능력":1},"error_path":"정답"},{"choice_id":"D","text":"선천 면역에는 기여하지만 적응 면역에는 방해가 된다.","vector":{"문장 독해력":-5},"error_path":"개념 혼동"},{"choice_id":"E","text":"낮에는 활성화되고 밤에는 비활성화된다.","vector":{"문장 독해력":-5},"error_path":"사실 무근"}]' WHERE id = 'W1_NON_P5_Q08';

-- test_questions 의 choices_json 갱신 (V0048 재시드 패턴, vector 포함)
DELETE FROM test_questions WHERE test_id LIKE 'diag_paper_%';

INSERT INTO test_questions
    (id, test_id, number, type, domain, sub_domain, passage, stem, points,
     correct_answer, choices_json, choice_explanations_json, intent,
     essay_keywords_json, essay_rubric_json, model_answer, created_at)
SELECT
    CONCAT('diag_tq_', q.id)                                                      AS id,
    CONCAT('diag_paper_', q.tier)                                                 AS test_id,
    ROW_NUMBER() OVER (PARTITION BY q.tier ORDER BY p.level, p.id, q.order_in_passage) AS number,
    '객관식'                                                                       AS type,
    q.question_type                                                               AS domain,
    p.genre                                                                       AS sub_domain,
    p.text_md                                                                     AS passage,
    CASE
        WHEN q.box_content IS NULL OR q.box_content = '' THEN q.stem
        ELSE CONCAT(q.stem, '\n<보기>\n', q.box_content)
    END                                                                           AS stem,
    10                                                                            AS points,
    q.correct_choice                                                              AS correct_answer,
    CAST(q.choices_json AS CHAR)                                                  AS choices_json,
    NULL                                                                          AS choice_explanations_json,
    NULL                                                                          AS intent,
    NULL                                                                          AS essay_keywords_json,
    NULL                                                                          AS essay_rubric_json,
    NULL                                                                          AS model_answer,
    NOW(6)                                                                        AS created_at
FROM diag_questions q
JOIN diag_passages  p ON p.id = q.passage_id
WHERE q.question_type <> '서술형';
